// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    OwnerAcceptor owner;

    function setUp() public {
        owner = new OwnerAcceptor();
        vm.prank(address(owner));
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount, address depositor) public {
        // keep the domain admissible: depositor must be a plain EOA-style payer, amount positive and sane
        vm.assume(depositor != address(c));
        vm.assume(depositor != address(owner));
        vm.assume(depositor != address(this));
        uint256 amt = bound(amount, 1, 1e18);

        // fund c through its payable fallback from a fuzzed depositor
        vm.deal(depositor, amt);
        vm.prank(depositor);
        (bool ok, ) = address(c).call{value: amt}("");
        require(ok, "deposit failed");

        // owner drains via withdrawAll(); owner is a contract that accepts ETH,
        // so the reference's transfer of the full balance succeeds
        owner.drain(c);

        // GENERAL RULE: after withdrawAll(), c holds no Ether.
        // Reference: withdraws address(this).balance -> balance == 0 (always holds).
        // Mutant: withdraw(0) -> balance stays amt > 0 (violated for every funded input).
        assertTrue(address(c).balance == 0, "withdrawAll must drain the whole balance");
    }
}

contract OwnerAcceptor {
    function drain(SimpleWallet c) external {
        c.withdrawAll();
    }
    receive() external payable {}
}
